#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n,k;scanf("%d %d",&n,&k);vector<long long>a(n);
for(int i=0;i<n;++i)scanf("%lld",&a[i]);
long long s=0;for(int i=0;i<k;++i)s+=a[i];
long long best=s;
for(int i=k;i<n;++i){s+=a[i]-a[i-k];best=max(best,s);}
printf("%.5f\n",(double)best/k);return 0;}

